"use client"

import { Button as BaseButton } from "@base-ui/react/button"
import { Loader2 } from "lucide-react"
import type { ComponentProps, ReactNode } from "react"

import {
  buttonVariants,
  type ButtonVariantProps,
} from "@/components/ui/button-variants"
import { cn } from "@/lib/utils"

/**
 * Props for the nk Button built on Base UI.
 */
type ButtonProps = ComponentProps<typeof BaseButton> &
  ButtonVariantProps & {
    /** Shows a spinner, sets aria-busy, and disables interaction. */
    readonly loading?: boolean
    /** Optional label announced while loading (defaults to children text context). */
    readonly loadingLabel?: ReactNode
  }

/**
 * Accessible button with nk product styling.
 *
 * Styles: `variant` + `size`. Behaviors like loading are props.
 * Icons, progress fill, and full-width are composition / className.
 */
const Button = ({
  className,
  variant,
  size,
  loading = false,
  loadingLabel,
  disabled,
  children,
  focusableWhenDisabled,
  ...props
}: ButtonProps) => {
  const isDisabled = Boolean(disabled || loading)

  return (
    <BaseButton
      className={cn(buttonVariants({ variant, size }), className)}
      disabled={isDisabled}
      focusableWhenDisabled={focusableWhenDisabled ?? loading}
      aria-busy={loading || undefined}
      data-loading={loading ? "" : undefined}
      {...props}
    >
      {loading ? (
        <>
          <Loader2 className="animate-spin" aria-hidden="true" />
          {loadingLabel ?? children}
        </>
      ) : (
        children
      )}
    </BaseButton>
  )
}

export { Button, buttonVariants }
export type { ButtonProps }

import { cva, type VariantProps } from "class-variance-authority"

/**
 * Visual variants for the nk Button.
 *
 * Keep this list to true visual styles. Behaviors like loading/progress/icons
 * are props or composition — not extra `variant` values.
 */
const buttonVariants = cva(
  "inline-flex shrink-0 items-center justify-center gap-2 rounded-md text-sm font-medium whitespace-nowrap transition-colors outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background disabled:pointer-events-none disabled:opacity-50 [&_svg]:pointer-events-none [&_svg]:size-4 [&_svg]:shrink-0",
  {
    variants: {
      variant: {
        default: "bg-primary text-primary-foreground hover:bg-primary/90",
        secondary:
          "bg-secondary text-secondary-foreground hover:bg-secondary/80",
        soft: "bg-secondary/70 text-secondary-foreground hover:bg-secondary",
        outline:
          "border border-border bg-background hover:bg-accent hover:text-accent-foreground",
        ghost: "hover:bg-accent hover:text-accent-foreground",
        destructive:
          "bg-destructive text-destructive-foreground hover:bg-destructive/90",
        link: "h-auto rounded-none px-0 text-foreground underline-offset-4 hover:underline",
      },
      size: {
        sm: "h-8 px-3 text-xs",
        default: "h-9 px-4 py-2",
        lg: "h-10 px-6",
        icon: "size-9",
        "icon-sm": "size-8",
        "icon-lg": "size-10",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  }
)

type ButtonVariantProps = VariantProps<typeof buttonVariants>

export { buttonVariants }
export type { ButtonVariantProps }
